SELECT 
FROM test_case tc
JOIN project p ON p.id = tc.project_id
WHERE tc.id = #{id}
  AND tc.deleted = 0
  AND p.owner_id = #{ownerId}

SELECT COUNT(*)
FROM test_case
WHERE project_id = #{projectId}
  AND name = #{name}
  AND deleted = 0

    AND id != #{excludingId}

